(40301, 'Job 24:15', 'Job', 24, 15, 'زناکار هم د تيارې په اِنتظار کښې وى، خيال يې دا وى چې د هيچا به په ما باندې نظر نۀ وى، او هغه مخ پټوى چې څوک مې ونۀ پېژنى.', 'زناکار هم د تیارې په انتظار کشې وی، خیال یې دا وی چې د هیچا به په ما باندې نظر نۀ وی، او هغه مخ پتوی چې چوک مې ونۀ پېژنی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_24_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40302, 'Job 24:16', 'Job', 24, 16, 'د شپې په وخت کښې غلۀ د کورونو کنډرې کوى، او د ورځې خوبونه کوى، او رڼا ته نۀ راوځى.', 'د شپې په وخت کشې غلۀ د کورونو کندرې کوی، او د ورجې خوبونه کوی، او رنا ته نۀ راوجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_24_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
